-- Large Scale Student Population Script
SET @org_id = 1;
SET @campus_id = (SELECT id FROM campuses LIMIT 1);
SET @standard_id = (SELECT id FROM standards LIMIT 1);
SET @section_id = (SELECT id FROM sections LIMIT 1);
SET @admission_type_id = (SELECT id FROM admission_type LIMIT 1);
SET @academic_year_id = (SELECT COALESCE((SELECT id FROM academic_years WHERE is_current = 1 LIMIT 1), (SELECT id FROM academic_years LIMIT 1)));

